const agent = $input.item.json;
const sub = $('Sub').item.json;
const sessionId = $('exec_data').item.json.sessionId || sub.sessionId || ('anon-' + $execution.id);
const rawSteps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
const steps = rawSteps.map(s => ({
  tool: s && s.action && s.action.tool != null ? s.action.tool : null,
  input: s && s.action ? (s.action.toolInput ?? null) : null,
  observation: String(s && s.observation != null ? s.observation : '').slice(0, 100000),
}));
return { json: {
  session_id: String(sessionId),
  transport: sub.env != null ? String(sub.env) : null,
  input: String(sub.chatInput != null ? sub.chatInput : ''),
  output: String(agent.output != null ? agent.output : ''),
  steps,
} };

// Preserve the sub-workflow return contract exactly: re-emit the agent
// node's output unchanged (Save Trace's insert result must not leak to callers).
return $('darwin').all();
